// KeywordResearchServiceHandler is an implementation of the san.tower.v1.KeywordResearchService
// service.
type KeywordResearchServiceHandler interface {
	// ListResearches lists the researches right in a folder, or of every
	// folder, by name.
	ListResearches(context.Context, *connect.Request[v1.ListResearchesRequest]) (*connect.Response[v1.ListResearchesResponse], error)
	GetResearch(context.Context, *connect.Request[v1.GetResearchRequest]) (*connect.Response[v1.GetResearchResponse], error)
	// CreateResearch makes a research in folder_id (0: at the top), with the
	// default filters (Indonesia, Past 12 months, All categories, Web
	// Search) and deep limit 2. Names are unique, ignoring case. The seed may
	// be empty (the page's New research no longer asks it): Run then refuses
	// (InvalidArgument) until one is set.
	CreateResearch(context.Context, *connect.Request[v1.CreateResearchRequest]) (*connect.Response[v1.CreateResearchResponse], error)
	// UpdateResearch changes a research's name, description, seed, deep
	// limit, filters and connection. Its graph stays: Run adds a new seed to
	// it, and asks before it clears a graph made with other filters.
	UpdateResearch(context.Context, *connect.Request[v1.UpdateResearchRequest]) (*connect.Response[v1.UpdateResearchResponse], error)
	// DeleteResearch deletes a research and its graph. A research that is
	// running or waiting is stopped first.
	DeleteResearch(context.Context, *connect.Request[v1.DeleteResearchRequest]) (*connect.Response[v1.DeleteResearchResponse], error)
	// DuplicateResearch copies a research, its graph included, as "<name>
	// (copy)" in the same folder. A running research's graph is copied as it
	// is at that moment.
	DuplicateResearch(context.Context, *connect.Request[v1.DuplicateResearchRequest]) (*connect.Response[v1.DuplicateResearchResponse], error)
	// MoveResearches puts researches in a folder (0: at the top).
	MoveResearches(context.Context, *connect.Request[v1.MoveResearchesRequest]) (*connect.Response[v1.MoveResearchesResponse], error)
	// The folders of researches, a tree of their own, as the workflows' and
	// the knowledge's. Deleting a folder moves what was in it up one level.
	ListResearchFolders(context.Context, *connect.Request[v1.ListResearchFoldersRequest]) (*connect.Response[v1.ListResearchFoldersResponse], error)
	CreateResearchFolder(context.Context, *connect.Request[v1.CreateResearchFolderRequest]) (*connect.Response[v1.CreateResearchFolderResponse], error)
	UpdateResearchFolder(context.Context, *connect.Request[v1.UpdateResearchFolderRequest]) (*connect.Response[v1.UpdateResearchFolderResponse], error)
	DeleteResearchFolder(context.Context, *connect.Request[v1.DeleteResearchFolderRequest]) (*connect.Response[v1.DeleteResearchFolderResponse], error)
	// RunResearch starts the crawl: from the seed when the graph is empty,
	// else it goes on from where it was, looking up the Top keywords not yet
	// looked up within the deep limit. A seed keyword the graph does not
	// have as a seed yet is added first (depth 0, looked up first, then its
	// Top keywords to the deep limit); one that is an ordinary keyword of the
	// graph becomes a seed, and the keywords found through it come nearer.
	// A keyword is never looked up twice. Depth is the shortest distance
	// from any seed. Only one crawl runs in the tower at a time: another
	// research's makes it wait (WAITING). A graph made with other filters
	// (location, time range, category, search type) is refused
	// (FailedPrecondition) unless clear is set, which clears it first. A
	// research without a seed keyword is refused (InvalidArgument). It goes
	// on when the page closes.
	RunResearch(context.Context, *connect.Request[v1.RunResearchRequest]) (*connect.Response[v1.RunResearchResponse], error)
	// ExploreKeyword looks up one keyword of the graph once, past the deep
	// limit or a Rising one too; it waits its turn as a Run does.
	ExploreKeyword(context.Context, *connect.Request[v1.ExploreKeywordRequest]) (*connect.Response[v1.ExploreKeywordResponse], error)
	// StopResearch ends a crawl after the lookup it is doing, or takes a
	// waiting one out of the queue. What was found stays.
	StopResearch(context.Context, *connect.Request[v1.StopResearchRequest]) (*connect.Response[v1.StopResearchResponse], error)
	// ClearResearchGraph empties a research's graph. Refused while it runs.
	ClearResearchGraph(context.Context, *connect.Request[v1.ClearResearchGraphRequest]) (*connect.Response[v1.ClearResearchGraphResponse], error)
	// GetResearchGraph gives every keyword and relationship of a research's
	// graph, with the Leiden communities of its keywords.
	GetResearchGraph(context.Context, *connect.Request[v1.GetResearchGraphRequest]) (*connect.Response[v1.GetResearchGraphResponse], error)
	// AddToBlacklist adds keywords or phrases to a research's blacklist (the
	// user, 2026-11-12: "Add tab blacklist keyword"; "And in node when right
	// click add context menu add to blacklist, and remove the node and
	// child"). An entry matches a keyword when its words are in it as whole
	// words, in order and next to each other ("kode pos" matches "kode pos",
	// "kode pos jakarta" and "cek kode pos"; "pos" does not match "posisi").
	// Adding one takes every keyword it matches out of the graph with its
	// relationships, and every keyword then left without a path from any seed
	// (those found only through them); one also found from a keyword that
	// stays, stays. With keep_children only the keywords it matches go (the
	// user, 2026-11-12: "in blacklist, ask blacklist selected keyword or
	// selected keyword and child"). A crawl never adds a keyword it matches
	// again: it reads the blacklist at each lookup, so an entry added while
	// it runs counts from its next lookup. An entry that matches a seed
	// keyword is refused (InvalidArgument). With dry_run nothing changes: it
	// says what adding would take out. The research's pages get the removal
	// live (WatchResearch's removal) and the blacklist with the research.
	AddToBlacklist(context.Context, *connect.Request[v1.AddToBlacklistRequest]) (*connect.Response[v1.AddToBlacklistResponse], error)
	// RemoveFromBlacklist takes entries out of a research's blacklist: one,
	// several, or all of them, in one call (the user, 2026-11-12: "in
	// blacklist, add button delete all"; "and add delete selected"); its
	// pages get the research once. The keywords they took out of the graph
	// do not come back; a later lookup may find them again.
	RemoveFromBlacklist(context.Context, *connect.Request[v1.RemoveFromBlacklistRequest]) (*connect.Response[v1.RemoveFromBlacklistResponse], error)
	// GetTrendsOptions gives Google Trends' own filter lists (locations,
	// categories, time ranges, search types), read from Trends through a
	// San Remote connection the first time, then kept in the tower's data
	// folder. With country, that country's regions too.
	GetTrendsOptions(context.Context, *connect.Request[v1.GetTrendsOptionsRequest]) (*connect.Response[v1.GetTrendsOptionsResponse], error)
	// WatchResearch streams a research as it changes, for its page (the user,
	// 2026-11-11: "is crawl realtime update the graph? make it realtime"):
	// first a snapshot (the research, its whole graph and communities), then
	// each change as it happens: the research (status, progress, counts,
	// settings, blacklist), what each lookup wrote to the graph right after it
	// was written, with the communities worked out again, what a blacklist
	// entry took out, a new snapshot when the graph was cleared, and a
	// heartbeat every 15 seconds. Several pages can
	// watch one research. A page that falls behind is dropped (Unavailable),
	// never waited for, so it cannot hold the crawl: it watches again and
	// starts from a new snapshot. The stream ends after deleted, and when the
	// tower stops.
	WatchResearch(context.Context, *connect.Request[v1.WatchResearchRequest], *connect.ServerStream[v1.WatchResearchResponse]) error
	// WatchResearches streams the list of researches for the list page: first
	// every research of every folder and every folder, then a research each
	// time it changes (status, progress, counts, name), the whole list again
	// when researches or folders are made, moved or deleted, and a heartbeat
	// every 15 seconds.
	WatchResearches(context.Context, *connect.Request[v1.WatchResearchesRequest], *connect.ServerStream[v1.WatchResearchesResponse]) error
}

